import React, { useState, useEffect } from "react";
import axios from "axios";
import { API } from "../config";

function UserPanel({ token }) {
  const [challans, setChallans] = useState([]);

  const fetchMine = async () => {
    const userId = localStorage.getItem("uid");
    try {
      const res = await axios.get(`${API}/challan/user/${userId}`);
      setChallans(res.data);
    } catch (err) {
      console.error(err);
    }
  };

  const payChallan = async (id) => {
    try {
      await axios.post(`${API}/challan/pay/${id}`);
      alert("Challan paid");
      fetchMine();
    } catch (err) {
      console.error(err);
      alert("Error paying challan");
    }
  };

  useEffect(() => {
    fetchMine();
  }, []);

  return (
    <div style={{ padding: 20 }}>
      <h2>My Challans</h2>
      <button onClick={fetchMine}>Refresh</button>
      <table border="1" cellPadding="6">
        <thead>
          <tr>
            <th>#</th>
            <th>Vehicle</th>
            <th>Cause</th>
            <th>Fine</th>
            <th>Status</th>
            <th>Action</th>
          </tr>
        </thead>
        <tbody>
          {challans.map((c, i) => (
            <tr key={c._id}>
              <td>{i + 1}</td>
              <td>{c.vehicleNumber}</td>
              <td>{c.cause}</td>
              <td>{c.fine}</td>
              <td>{c.status}</td>
              <td>
                {c.status !== "Paid" && <button onClick={() => payChallan(c._id)}>Pay</button>}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

export default UserPanel;
